import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d as p,i as P,S as d}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"ICMP","description":"","frontmatter":{"title":"ICMP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/icmp.md","filePath":"cs/icmp.md","lastUpdated":1789023840000}'),c={name:"cs/icmp.md"};function h(C,a,I,_,m,E){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="icmp" tabindex="-1">ICMP <a class="header-anchor" href="#icmp" aria-label="Permalink to &quot;ICMP&quot;">​</a></h1><div class="epigraph"><p>ICMP 承载网络层的差错与诊断：目的不可达、超时、回显；它不是用户字节流。</p><footer>—— 据 Postel, RFC 792, Internet Control Message Protocol, 1981 整理</footer></div><p><a href="/cs/ip-fragment">上一课</a>可能找不到路由，或 <a href="/cs/ip-subnet">IP</a> 的 TTL 减到零。静默丢包让源主机无法区分「远」与「死」。缺口是 <strong>ICMP</strong>：对源 IP 回控制报文。本课不把 ping 当应用层协议课程，也不引入 DHCP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>路由器丢包若无信号，传输层只能靠超时猜测。RFC 792：目的不可达（网络/主机/端口等）、超时（TTL）、参数问题、源抑制（历史）、重定向、回显请求/应答。ICMP 封装在 IP 里，协议号 1。缺口不是新的 LPM 规则，而是这些消息的语义与限制：差错报文不要再对差错报文生成，以免风暴。</p><p>本课不把 ICMP 当隐蔽信道来讲。</p><p><span class="marginnote">Traceroute 利用 TTL=1,2,… 与超时消息探路径，是诊断工具，不是路由协议。路径上的过滤会使结果残缺。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>转发失败：构造 ICMP，源地址用出接口或路由器地址，目的是原包源地址，载荷含原 IP 头与部分数据以便匹配。主机 ping：回显请求，对端应答。端口不可达常由主机在无监听传输端口时发出，为后课 UDP 预留。</p>',9)),(e(),n(d,null,{default:r(()=>[P(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E4%B8%A2%E5%8C%85%3A%20%E6%97%A0%E8%B7%AF%E7%94%B1%E6%88%96%20TTL%22%5D%20--%3E%20ICMP%5B%22ICMP%20%E5%B7%AE%E9%94%99%E7%BB%99%E6%BA%90%22%5D%0A%20%20ECHO%5B%22%E5%9B%9E%E6%98%BE%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20REP%5B%22%E5%9B%9E%E6%98%BE%E5%BA%94%E7%AD%94%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ICMP 把网络层的失败接到端系统，但仍是尽力而为：ICMP 自己也会丢。端到端论证：应用不能只靠「没收到 ICMP」断定成功。许多站点过滤 ICMP，于是诊断与「路径 MTU 发现」变钝——PMTU 依赖「需要分片」类消息，本课点名，IPv6 课会强调不分片。</p><p>与<a href="/cs/signals">信号</a>类比：都是异步通知，但 ICMP 走网络，对象是 IP 端点不是 PID。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 ICMPv6 的全部类型列完（邻居发现在 IPv6 课）。不引入 ICMP 重定向作为默认安全实践——可被滥用，主机常忽略。地址如何自动配置、私网如何共享公网地址，下一课 DHCP 与 NAT。</p><p>源抑制在当代拥塞控制里已废弃，不应再依赖。重定向把主机的 LPM 改向，错误配置会把流量拐走，许多系统默认忽略。</p><p>回显与差错共用协议号，过滤策略要分开看类型。</p><p>后课默认：网络层可用 ICMP 报告失败与回显。地址分配与公私网边界，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ICMP（RFC 792）报告不可达、超时，并提供回显。</li><li>不为差错再发差错；诊断可被过滤。</li><li>地址配置与 NAT 是下一课。</li><li>出处：RFC 792；Kurose and Ross。</li></ul>',10))])}const u=i(c,[["render",h]]);export{M as __pageData,u as default};
